{
  "returncode": 0,
  "output": "==> app/assets/stylesheets/proposals/featured_proposal.scss <==
.proposal-featured {
  min-height: $line-height * 3.5;

  .info {
    > :last-child {
      &::before {
        @include circle-separator;
      }
    }
  }

  .supports {
    @include supports;
    background: none;
    border: 0;
    padding-bottom: 0;
    padding-top: 0;

    &::after {
      content: none;
    }

    .progress,
    .total-supports {
      display: none;
    }

    .button-support {
      background: $body-font-color;
      color: $featured;
      margin-top: 0;

      &:hover {
        @extend %body-colors;
      }
    }

    .participation-not-allowed {
      background: $featured;
      padding-top: 0;

      a {
        color: inherit;
      }

      p {
        color: $color-warning;
        font-size: $small-font-size;
        line-height: $line-height;
      }
    }

    .supported {
      background: none;
      border: 0;
      font-size: $small-font-size;
      margin-bottom: 0;
      margin-top: 0;
      padding: 0;
    }
  }

  .share-supported {

    .social-share-button .ssb-icon {
      background: none;
      color: inherit;
      height: rem-calc(33);

      &::before {
        font-size: rem-calc(18);
        line-height: rem-calc(33);
      }
    }
  }
}

==> app/assets/stylesheets/proposals/featured_proposals.scss <==
.featured-proposals {
  background: $featured;
}

==> app/assets/stylesheets/proposals/form.scss <==
.proposal-form {
  @extend %public-form;
}

==> app/assets/stylesheets/proposals/geozones.scss <==
.proposals-geozones {
  a {
    @include focus-outline-on-img;
  }
}

==> app/assets/stylesheets/proposals/new.scss <==
.proposal-new {
  @extend %public-form-header;

  header h1 {
    @include has-fa-icon(lightbulb, regular, after);
  }

  aside {
    margin-top: $line-height;
  }

  .recommendations li::before {
    color: $proposals;
  }
}

==> app/assets/stylesheets/proposals/summary.scss <==
.proposals-summary {
  .panel,
  .basic-content {
    min-height: 0;
  }
}

==> app/assets/stylesheets/widgets/feeds/feed.scss <==
.widget-feed {

  .feed-description {

    p {
      font-size: $small-font-size;
      margin-bottom: 0;
    }
  }

  .feed-content {

    .debate,
    .proposal {
      margin-bottom: 0;
      margin-top: 0;
      padding: calc($line-height / 2) 0;
    }
  }

  .no-items {
    margin-top: $line-height;
  }
}

==> app/assets/stylesheets/widgets/feeds/participation.scss <==
.feeds-participation {
  @include flex-with-gap;
  flex-wrap: wrap;

  .feed-proposals {
    flex-basis: rem-calc(480);
    flex-grow: 2;
  }

  .feed-debates {
    flex-basis: rem-calc(240);
    flex-grow: 1;
  }

  .feed-proposals,
  .feed-debates {
    display: flex;
    flex-direction: column;
    margin-top: $line-height;

    .feed-content {
      flex-grow: 1;
    }
  }

  .sdg-tag-list {
    margin-top: calc($line-height / 2);
  }
}

==> app/assets/stylesheets/widgets/feeds/proposal.scss <==
.feed-proposals .proposal {
  @include grid-row-nest;
  clear: both;

  .feed-image {
    display: inline-block;
    height: rem-calc(120);
    overflow: hidden;
    width: 100%;

    @include breakpoint(medium) {
      height: rem-calc(96);
    }

    img {
      max-width: none;
      width: 100%;
    }
  }
}
