  "returncode": 0,
  "output": "class Admin::Dashboard::IndexComponent < ApplicationComponent
  include Header

  def title
    t("admin.dashboard.index.title")
  end

  private

    def info
      sanitize t("admin.dashboard.index.info")
    end

    def email_link
      mail_to "info@consulfoundation.org"
    end

    def website_link
      link_to "https://consuldemocracy.org", "https://consuldemocracy.org"
    end
end
<% provide :main_class, "admin-dashboard-index" %>
<%= header(skip_section_title: true) %>

<p><%= t("admin.dashboard.index.description", org: setting["org_name"]) %></p>

<%= info %>

<address>
  <%= email_link %>
  <%= website_link %>
</address>
.admin-dashboard-index {
  > header h2 {
    border-bottom: 1px solid $border;
    text-transform: uppercase;
  }

  address {
    > :not(:last-child) {
      &::after {
        content: "";
        display: block;
        margin-bottom: calc($line-height / 3);
      }
    }

    a {
      &[href^="mailto:"] {
        @include has-fa-icon(envelope, regular);
      }

      &[href^="http"] {
        @include has-fa-icon(globe, solid);
      }

      &::before {
        margin-#{$global-right}: 0.2em;
        transform: translateY(-0.2em);
      }
    }
  }
}
<div class="row column communities-participant">

  <ul class="tabs" id="communities_show_tabs"
      data-deep-link="true"
      data-update-history="true"
      data-deep-link-smudge="true"
      data-deep-link-smudge-delay="500"
      data-tabs>

    <li class="tabs-title is-active">
      <%= link_to "#tab-participants" do %>
        <h3>
          <%= t("community.show.tab.participants") %>
          <span class="js-comments-count">(<%= @participants.count %>)</span>
        </h3>
      <% end %>
    </li>

    <% if @community.proposal.present? %>
      <li class="tabs-title">
        <%= link_to "#tab-polls" do %>
          <h3>
            <%= t("communities.subnav.surveys") %>
            <span class="js-comments-count">(<%= @community.proposal.polls.count %>)</span>
          </h3>
        <% end %>
      </li>
    <% end %>
  </ul>

  <div class="tabs-content" data-tabs-content="communities_show_tabs">
    <div class="tabs-panel is-active" id="tab-participants">
      <%= render partial: "participant", collection: @participants %>
    </div>

    <% if @community.proposal.present? %>
      <div class="tabs-panel topic-show" id="tab-polls">
        <%= render partial: "poll", collection: @community.proposal.polls %>
      </div>
    <% end %>
  </div>
</div>
"
}

